function describe(value) {
  if (value) {
    console.log("truthy");
  } else {
    console.log("falsy");
  }
}

describe(0);
describe("0");
describe("");
describe(null);
describe([]);

const day = "sat";

switch (day) {
  case "sat":
  case "sun":
    console.log("Weekend");
    break;
  case "fri":
    console.log("Almost weekend");
    break;
  default:
    console.log("Weekday");
}

function shippingCost(country, total) {
  if (total >= 100) return 0;        // free shipping, whatever the country
  if (country === "FR") return 5;
  return 15;
}

console.log(shippingCost("FR", 120));
console.log(shippingCost("FR", 40));
console.log(shippingCost("US", 40));

